# Function to extract emails
def extract_emails(email_string):
    # Pattern to capture emails in 'Name <email>' or 'email' formats
    pattern = r'([\w\s.,-]+)?<?([\w.-]+@[\w.-]+)>?'
    matches = re.findall(pattern, email_string)

    # Format the output as ["Name <email>", ...]
    formatted_emails = []
    for name, email in matches:
        if name.strip():  # Check if name exists
            formatted_emails.append(f"{name.strip()} <{email.strip()}>")
        else:
            formatted_emails.append(f"<{email.strip()}>")

    return formatted_emails


# Process first part of the emails
emails = extract_emails(email)

print(emails)
